INSERT INTO changelog_entries(version,title,summary,content,category,published_at,affected_route,created_at,updated_at) SELECT '2.56.0','Известия за запазени процедури и срокове','Активирайте известия в браузъра и проверете доставката от профила. Настройките за промени и срокове управляват изпращането.','["Web Push известията се активират само с ваше разрешение. Профилът проверява реалния абонамент и предлага тест през сървъра.","Промените по запазени процедури и напомнянията за срокове спазват избраните настройки и броя дни. Имейл каналът остава неактивен.","Поканата за активиране се показва след приветствието и половината страница, най-много веднъж за 24 часа.","Всеки браузър има отделен абонамент. Изходът премахва абонамента за сесията, а невалидните абонаменти се почистват автоматично."]','feature','2026-09-19','/profile',datetime('now'),datetime('now') WHERE NOT EXISTS (SELECT 1 FROM changelog_entries WHERE version='2.56.0');
